(function(){tinymce.PluginManager.requireLangPack('ruby');tinymce.create('tinymce.plugins.RubyPlugin',{init:function(ed,url){ed.addCommand('mceRuby',function(){ed.windowManager.open({file:url+'/dialog.htm',width:800+parseInt(ed.getLang('ruby.delta_width',0)),height:310+parseInt(ed.getLang('ruby.delta_height',0)),inline:1},{plugin_url:url,})});ed.addButton('ruby',{title:'ruby.desc',cmd:'mceRuby',image:url+'/img/ruby.png'});ed.onNodeChange.add(function(ed,cm,n){cm.setActive('ruby',n.nodeName=='IMG')});ed.onKeyDown.add(function(ed, e) { if (e.charCode == 13 || e.keyCode == 13 ) { var nodeName = tinymce.activeEditor.selection.getNode().nodeName;if(nodeName == 'RT' || nodeName == 'RP' || nodeName == 'RUBY'  ) {tinyMCE.activeEditor.selection.select(tinymce.activeEditor.dom.getParent(tinyMCE.activeEditor.selection.getNode(),'span'), true);tinyMCE.activeEditor.selection.collapse(false);}}});},createControl:function(n,cm){return null},getInfo:function(){return{longname:'Ruby annotation plugin',author:'Dr Joseph Baxter',authorurl:'http://rogo-oss.nottingham.ac.uk/',infourl:'https://rogo-eassessment-docs.atlassian.net',version:"1.0"}}});tinymce.PluginManager.add('ruby',tinymce.plugins.RubyPlugin)})();